const described = {
  'Wait statistics': 'Accumulated measurements of time SQL Server workers spent waiting for resources or events; interpret them as workload clues and correlate them with the affected query and interval.',
  'sys.dm_os_wait_stats': 'Instance-level counters for waits that have completed. They are cumulative since startup or reset, omit current waits, and do not attribute waits to a query; take timestamped deltas.',
  'sys.dm_exec_requests': 'One row per request currently executing in SQL Server; use it for live request status, elapsed and CPU time, reads, wait type, and blocking relationships.',
  'sys.dm_exec_sessions': 'Session-level connection and activity metadata. It helps relate requests to login, client, host, and session settings but a sleeping session is not itself a running query.',
  'sys.dm_exec_query_stats': 'Aggregated execution metrics for completed executions associated with cached plans. Rows can disappear when plans leave cache, so it is not durable history.',
  'sys.dm_exec_sql_text': 'Returns SQL text for a SQL handle, including batch or module text. Handle and offsets determine which statement within a batch is relevant.',
  'sys.dm_exec_query_plan': 'Returns cached plan XML for a plan handle. A plan can be absent after cache eviction, and an estimated/cached plan does not show every actual runtime row count.',
  'sys.dm_os_waiting_tasks': 'Shows tasks that are currently waiting and their resources/blocking context. It complements completed historical wait counters and is a transient snapshot.',
  'sys.dm_io_virtual_file_stats': 'Cumulative file-level I/O counts, bytes, and stall times since counters began; derive latency from deltas and separate data-file and log-file activity.',
  'sys.dm_db_index_usage_stats': 'Counts index seeks, scans, lookups, and updates since counters began. Resets and workload observation windows matter; low reads do not alone prove an index is useless.',
  'sys.dm_db_missing_index_details': 'One component of optimizer-generated missing-index suggestions. Recommendations are limited, can overlap, omit write/storage cost and some index designs, and must be tested against the full workload.',
  'Query Store': 'Database-persisted query text, plans, and aggregated performance history, useful for changes over time where the plan cache is transient. Check its state, capture policy, size, and retention.',
  'Query Store runtime statistics': 'Per-plan metrics aggregated in configured time intervals, including execution count and runtime/CPU/I/O measures; averages can hide tails and parameter cohorts.',
  'Query Store wait statistics': 'Wait categories associated with Query Store tracked query plans on supported versions; it improves query-level diagnosis but does not replace live task inspection or workload correlation.',
  'Query Store plan forcing': 'Requests that a previously recorded plan be used. The optimizer can fail to force it and emit an event; compare outcome, monitor regressions, and unforce when it is no longer appropriate.',
  'Extended Events': 'A low-overhead, configurable event infrastructure for targeted diagnosis. Select narrowly scoped events, actions, predicates, and retention because broad/high-volume collection still costs resources and may capture sensitive values.',
  'event session': 'A configured Extended Events collection that specifies events, actions, predicates, and targets; start/stop it deliberately and avoid collecting everything indefinitely.',
  'event target': 'Destination that buffers, aggregates, or persists event data. The target affects durability, volume, and how evidence is queried.',
  'ring_buffer target': 'In-memory Extended Events target useful for short-lived inspection; it is bounded and volatile, so it can overwrite or lose older evidence and should not be treated as durable logging.',
  'event_file target': 'Extended Events target that writes event data to files for durable post-event analysis; plan rollover, size, access, and retention.',
  'system_health session': 'Built-in Extended Events session that captures selected health diagnostics, including useful severe errors and deadlock evidence. Its bounded target rolls over; inspect the configured files and window.',
  'SQL Server Profiler legacy boundary': 'Profiler and SQL Trace are legacy tracing tools; prefer Extended Events for new SQL Server diagnostics, while recognizing existing environments may still contain traces.',
  'Performance Monitor counter': 'Windows performance counter sampled over time to correlate SQL Server with OS CPU, memory, disk, and network behavior. Counter rate and scope must match the diagnostic question.',
  'Database Engine Tuning Advisor boundary': 'Workload-based tool that can propose indexes or partitioning configurations. Treat output as candidates to review and validate, not automatic proof or a replacement for workload-wide design.',
  'sys.dm_os_schedulers': 'Scheduler-level view of online schedulers and worker/task queues. Runnable queue length and active workers add CPU scheduling context but must be correlated with processor utilization and workload.',
  'sys.dm_os_sys_info': 'Returns SQL Server host and engine startup information, including `sqlserver_start_time`; use it to identify a counter lifetime boundary, not as historical telemetry.',
  'sys.dm_os_performance_counters': 'Exposes SQL Server performance counters and raw values. Interpret `cntr_type`, instance, base counters, and rate semantics correctly; take timed samples for rates.',
  'sys.dm_exec_query_memory_grants': 'Lists queries that have requested or received execution memory grants, including grant and wait state. Combine with plan estimates and concurrency to diagnose grant pressure.',
  'sys.dm_exec_procedure_stats': 'Aggregated performance statistics for cached stored-procedure plans. Rows disappear with plan eviction and do not represent durable procedure history.',
  'sys.dm_exec_cached_plans': 'Describes cached query plans and their cache-object metadata. Cache presence is transient and should not be confused with persisted Query Store history.',
  'sys.dm_db_task_space_usage': 'Reports tempdb space allocated/deallocated by task for active requests, helping locate request-level tempdb use. Capture while the task exists.',
  'sys.dm_db_session_space_usage': 'Reports tempdb allocations/deallocations attributed to sessions, often after task accounting is aggregated; interpret with session lifetime and request state.',
  'sys.query_store_query': 'Query Store catalog view for tracked query identities and context settings. A query text can have multiple entries under different contexts or module execution.',
  'sys.query_store_plan': 'Query Store catalog view of persisted plan records associated with query entries. Stored plans are estimated plan representations, not a full actual runtime trace.',
  'sys.query_store_runtime_stats': 'Query Store catalog view with interval-aggregated runtime measures per plan; use its interval relation and execution counts to avoid mixing periods.',
  'sys.query_store_wait_stats': 'Query Store catalog view with aggregated wait-category data for tracked plans and intervals where supported/enabled; interpret collection support and aggregation scope.',
  'sys.query_store_runtime_stats_interval': 'Query Store catalog view that defines the time windows used for runtime aggregation; align interval IDs and UTC boundaries during comparisons.',
  'sys.database_query_store_options': 'Reports configured and actual Query Store state, capture mode, storage use/limit, and read-only reason. Verify actual state before interpreting absent history.',
  'sp_query_store_force_plan': 'Requests that Query Store force a plan previously recorded for the query. Forcing can fail; check status/events and measure outcome.',
  'sp_query_store_unforce_plan': 'Removes Query Store plan forcing for a query/plan pair so normal optimization can resume; verify the next plan and workload behavior.',
  'xml_deadlock_report event': 'Extended Events event containing a deadlock graph with participants, resources, and victim. Use it to reconstruct a cycle and access order; a deadlock graph is not an ordinary blocking snapshot.',
  'CPU saturation': 'A sustained lack of runnable CPU capacity relative to demand, shown through OS and SQL scheduler evidence. High CPU in one query differs from instance saturation; inspect CPU per operation and concurrency.',
  'High logical reads': 'Many buffer-pool page accesses, which consume CPU and memory bandwidth even when no storage read occurs. Often points to excessive rows/pages processed or repeated lookups, not necessarily slow disks.',
  'Physical read latency': 'Time to fetch pages from storage into SQL Server buffers. Correlate file-level deltas and PAGEIOLATCH waits with I/O volume, storage contention, and query read patterns.',
  'Transaction-log write latency': 'Delay in flushing committed log records. Measure log-file write deltas and WRITELOG waits; causes include storage latency, high commit frequency, and log-path contention.',
  'Memory pressure': 'Competition for memory across buffer cache, query execution grants, OS, and other consumers. Distinguish page-read churn from grant starvation and external OS pressure.',
  'Memory grant wait': 'A query waits to receive workspace memory for memory-intensive operators such as sorts or hashes; inspect waiting and granted requests alongside plan estimates and concurrency.',
  'RESOURCE_SEMAPHORE': 'Wait indicating a query is queued for a query execution memory grant. Find which requests hold or request grants and reduce excessive estimates/work before indiscriminately increasing memory.',
  'PAGEIOLATCH wait': 'A task waits for a data/index page read into the buffer pool. It can reflect slow storage, but also excessive physical reads; inspect file latency and query read volume together.',
  'WRITELOG wait': 'A task waits for transaction log flush completion. Relate wait time to log-device latency, commit rate, transaction size, and durability requirements.',
  'SOS_SCHEDULER_YIELD wait': 'A worker yields its scheduler after consuming its quantum. High signal can indicate CPU pressure or CPU-intensive work; confirm runnable queues, CPU use, and query cost before changing settings.',
  'CXPACKET wait': 'Parallel exchange wait associated with producer threads in current SQL Server versions. SQL Server 2022+ tracks exchange synchronization using additional CXSYNC_* waits; older builds grouped some synchronization under CXPACKET. It is not automatically harmful: inspect build, plan, skew, CPU, and duration. [Wait-type version notes](' + urls.waitTypes + ')',
  'CXCONSUMER wait': 'Wait associated with consumer threads in parallel exchanges, commonly expected coordination. SQL Server 2022+ has additional CXSYNC_* categories; evaluate version, plan shape, and skew rather than treating counts as a standalone defect. [Wait-type version notes](' + urls.waitTypes + ')',
  'THREADPOOL wait': 'A request cannot obtain a worker thread. Investigate worker exhaustion, blocking chains, excessive concurrency, long requests, and connection/request patterns; increasing worker limits alone may not fix the cause.',
  'Lock blocking': 'A transaction holds a lock needed by another request. Identify the blocker and chain, transaction age, lock resource, and application transaction scope; distinguish blocking from deadlock cycles.',
  'Deadlock frequency': 'Rate of cyclic lock/resource dependencies that SQL Server resolves by aborting a victim. Capture deadlock graphs and identify competing access order or transaction design.',
  'Tempdb contention': 'Competition for tempdb allocation, metadata, or I/O resources. Separate in-memory latch contention from physical I/O and spills, then use evidence to choose configuration or query changes.',
  'Tempdb spill': 'A sort/hash or similar operation writes intermediate work to tempdb, often because memory grant or cardinality estimates were insufficient. Inspect plan warnings, rows, and grant feedback; spills are symptoms, not an automatic mandate to add memory.',
  'Connection-pool exhaustion': 'The application cannot obtain a pooled connection promptly, often due to long-held connections, leaked disposal, slow operations, or pool configuration. It can look like a database outage while SQL Server has capacity.',
  'Compilation storm': 'A burst of simultaneous query compilation consumes CPU and locks/resources, often due to ad hoc variation or recompilation. Inspect compile rate and query text patterns; parameterization and SQL Server 2025 OPTIMIZED_SP_EXECUTESQL may be relevant with appropriate workload testing.',
  'Parameter-sensitive regression': 'A cached plan suits some parameter values but performs poorly for others because selectivity differs. Compare parameter cohorts and plan history; options include query redesign, PSP/OPPO eligibility, or carefully tested mitigation.',
  'Long-running transaction': 'A transaction remains open while doing work or waiting, retaining locks and log state and potentially delaying cleanup. Find its owner and lifecycle before killing it, which causes rollback work.',
  'Storage throughput limit': 'The storage path is saturated in operations, bandwidth, or latency for the workload. Measure data and log paths separately and correlate queueing and workload demand; a product specification alone does not establish usable throughput.',
  'Queueing delay': 'Time work spends waiting for a constrained resource, which rises sharply as utilization approaches capacity. Include queue and service time when explaining observed response time.',
  "Little's Law workload estimate": 'For a stable system, average work in the system L equals arrival rate lambda times average time in the system W. It provides a consistency check for concurrency and latency, not a causal diagnosis or a tail-latency formula.',
  'Tail latency': 'Slow-end response behavior, commonly reported with p95 or p99 rather than only an average. It can worsen from rare waits, queueing, skew, retries, or outliers even while the mean looks acceptable.',
  'Baseline comparison': 'Comparison with a representative prior window under similar traffic, data shape, configuration, and cache conditions. Record restart/reset boundaries and avoid treating unlike workloads as a controlled comparison.',
  'Regression detection': 'Identifying a statistically and operationally meaningful degradation against a defined baseline, segmented by query, parameter, workload, and time. Confirm signal before changing production.',
  'Reproduce representative workload': 'Recreate realistic query mix, concurrency, parameter distribution, data size, and arrival pattern. A single query in isolation can miss contention and queueing effects.',
  'Capture query and plan baseline': 'Store query identity, plan, runtime distributions, CPU, reads, waits, parameter cohort, configuration, and observation window before change so later comparisons have context.',
  'Change one factor at a time': 'Make a bounded change with a hypothesis and rollback route, then measure it under comparable conditions. Multiple simultaneous changes make causation and regression attribution difficult.',
  'Query Store plan comparison': 'Compare plan versions and interval-level runtime measures for the same query, including execution count and resource use; account for context settings and changing parameter mix.',
  'Index change impact': 'Evaluate read improvement against added storage, write amplification, maintenance, concurrency, and plan effects across all important queries, not just the motivating statement.',
  'Statistics update decision': 'Update statistics when stale or misleading distribution data plausibly drives a bad estimate, after inspecting modification and sampling context. Updates can trigger recompilation and do not guarantee a better plan.',
  'Parameter-sensitive mitigation': 'Choose mitigation after measuring parameter cohorts: query shape, indexes/statistics, PSP/OPPO eligibility, recompile, or hints may fit different cases. Validate plan stability and compile cost.',
  'Query hint rollback plan': 'Document the hint scope, expected effect, monitoring criteria, expiry/review date, and exact reversal. Hints constrain optimizer choices and can become harmful as data and engine versions change.',
  'MAXDOP configuration boundary': 'Controls maximum parallel worker use for a query or configuration scope; it is not a universal CPU throttle. Tune using topology, workload, parallel plans, and Microsoft guidance for the current SQL Server release.',
  'Cost threshold for parallelism': 'Estimated optimizer cost threshold for considering parallel plans, not a millisecond duration or direct CPU limit. The best value depends on workload; raising it changes plan choices and must be tested.',
  'Batch-size reduction': 'Smaller transactions can reduce lock duration, log bursts, and memory/resource spikes, but increase round trips and overhead. Measure a batch-size curve rather than assuming smaller is always better.',
  'Application timeout diagnosis': 'A client timeout is an observation at the application boundary, not proof SQL Server stopped work. Correlate request, cancellation behavior, retries, server execution, and pool occupancy.',
  'Connection pooling diagnosis': 'Inspect pool wait time, connection lifetime/disposal, concurrency, per-connection settings, and server session state. Pool saturation and server worker starvation are distinct queues.',
  'Capacity headroom': 'Unused capacity under expected peak and failure conditions, measured for the limiting resource. Capacity planning includes growth, concurrency, operational jobs, and failover margin.',
  'Before-and-after measurement': 'Compare the same outcomes under equivalent workload and configuration, using distributions and normalized resource cost; account for cache warmup, background activity, and counter resets.',
  'p50 latency': 'Median response time: half of measured requests complete no slower and half no faster. It describes typical behavior but can hide tail degradation.',
  'p95 latency': 'The 95th percentile response time: 95% of observations are no slower, while 5% are slower. Sample size, window, and workload segmentation matter.',
  'p99 latency': 'The 99th percentile response time, sensitive to rare slow events and requiring enough observations for a stable estimate. Track it with throughput and error rate.',
  'Throughput per second': 'Completed useful operations per unit time. Higher request arrival rate is not higher successful throughput if queues, failures, or retries grow.',
  'Logical reads per operation': 'Buffer-pool pages touched by a representative operation, a useful normalized measure of work independent of whether pages came from storage during that execution.',
  'CPU time per operation': 'CPU consumed per completed business operation, useful for comparing efficiency while controlling for throughput and query mix.',
  'Rollback and mitigation plan': 'Predefine how to reverse the change, restore prior settings/plans, or route traffic away, and name measurable triggers and decision ownership.',
  'Canary validation': 'Expose a small controlled portion of traffic to the change and compare it with a control group while monitoring errors, latency tails, and resource costs.',
  'Load test workload realism': 'A load test should approximate production data volume, parameter distribution, concurrency, think time, arrival bursts, and background work; unrealistic tests can rank changes incorrectly.'
};
for (const [group, items] of Object.entries(groupItems)) for (const item of items) if (!described[item]) throw new Error('Missing exact-item explanation: ' + item);
const allItems = Object.values(groupItems).flat();
const bibliography = sourceUrls.map(url => '- [Microsoft Learn](' + url + ')').join('\n');
